  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON BINARY r.CONSTRAINT_SCHEMA=BINARY k.CONSTRAINT_SCHEMA AND BINARY r.CONSTRAINT_NAME=BINARY k.CONSTRAINT_NAME AND BINARY r.TABLE_NAME=BINARY k.TABLE_NAME WHERE BINARY k.TABLE_SCHEMA=BINARY DATABASE() AND BINARY k.TABLE_NAME='medical_record_reference_version' AND BINARY k.CONSTRAINT_NAME='mrc57_reference_record' AND k.COLUMN_NAME='record_id' AND k.ORDINAL_POSITION=1 AND k.POSITION_IN_UNIQUE_CONSTRAINT=1 AND BINARY k.REFERENCED_TABLE_SCHEMA=BINARY DATABASE() AND k.REFERENCED_TABLE_NAME='medical_record' AND k.REFERENCED_COLUMN_NAME='id' AND r.UNIQUE_CONSTRAINT_NAME='PRIMARY' AND r.DELETE_RULE='RESTRICT' AND r.UPDATE_RULE='RESTRICT')=1 AND
