  (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE BINARY TRIGGER_SCHEMA=BINARY DATABASE() AND (BINARY EVENT_OBJECT_TABLE IN ('medical_record_correction_state','medical_record_correction_history','medical_record_command','medical_record_reference_version','medical_record','medical_record_item','medical_record_attachment') OR BINARY LEFT(TRIGGER_NAME,6)=BINARY 'mrc57_'))=22 AND
  (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE BINARY TRIGGER_SCHEMA=BINARY DATABASE() AND BINARY TRIGGER_NAME='mrc57_history_insert' AND BINARY EVENT_OBJECT_TABLE='medical_record_correction_history' AND EVENT_MANIPULATION='INSERT' AND ACTION_TIMING='BEFORE' AND ACTION_ORDER=1 AND ACTION_ORIENTATION='ROW' AND ACTION_CONDITION IS NULL AND CHARACTER_SET_CLIENT='utf8mb4' AND COLLATION_CONNECTION LIKE 'utf8mb4\_%' AND DATABASE_COLLATION LIKE 'utf8mb4\_%' AND (FIND_IN_SET('STRICT_TRANS_TABLES',SQL_MODE)>0 OR FIND_IN_SET('STRICT_ALL_TABLES',SQL_MODE)>0) AND BINARY ACTION_STATEMENT=BINARY 'BEGIN
  IF NEW.record_id NOT BETWEEN 1 AND 9007199254740991 OR NEW.actor_id NOT BETWEEN 1 AND 9007199254740991 OR NEW.before_version NOT BETWEEN 1 AND 9007199254740991 OR NEW.after_version NOT BETWEEN 1 AND 9007199254740991 OR NEW.history_sequence NOT BETWEEN 0 AND 9007199254740991 THEN
