END')=1 AND
  (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE BINARY TRIGGER_SCHEMA=BINARY DATABASE() AND BINARY TRIGGER_NAME='mrc57_state_update' AND BINARY EVENT_OBJECT_TABLE='medical_record_correction_state' AND EVENT_MANIPULATION='UPDATE' AND ACTION_TIMING='BEFORE' AND ACTION_ORDER=1 AND ACTION_ORIENTATION='ROW' AND ACTION_CONDITION IS NULL AND CHARACTER_SET_CLIENT='utf8mb4' AND COLLATION_CONNECTION LIKE 'utf8mb4\_%' AND DATABASE_COLLATION LIKE 'utf8mb4\_%' AND (FIND_IN_SET('STRICT_TRANS_TABLES',SQL_MODE)>0 OR FIND_IN_SET('STRICT_ALL_TABLES',SQL_MODE)>0) AND BINARY ACTION_STATEMENT=BINARY 'BEGIN
  IF NOT ((BINARY NEW.record_id <=> BINARY OLD.record_id) AND (BINARY NEW.patient_id <=> BINARY OLD.patient_id) AND (BINARY NEW.owner_user_id <=> BINARY OLD.owner_user_id) AND (BINARY NEW.baseline_content_version <=> BINARY OLD.baseline_content_version) AND (BINARY NEW.created_at <=> BINARY OLD.created_at)) THEN
